using System.ComponentModel.DataAnnotations;
using TecniControl2026.Web.Data.Abstractions;
using TecniControl2026.Web.Data.Enums;

namespace TecniControl2026.Web.Data.Entities
{
    public class ServiceOrder : IId
    {
        [Key]
        public Guid Id { get; set; }

        // Number visible to the customer, generated by the database
        public int Number { get; set; }

        public Guid DeviceId { get; set; }
        public Device Device { get; set; } = null!;

        // Reception
        public DateTime ReceptionDate { get; set; }

        public Guid ReceivedById { get; set; }
        public User ReceivedBy { get; set; } = null!;

        [MaxLength(500)]
        public required string ReportedIssue { get; set; }

        [MaxLength(500)]
        public string? Accessories { get; set; }

        // Technical attention
        public Guid? TechnicianId { get; set; }
        public User? Technician { get; set; }

        [MaxLength(2000)]
        public string? Diagnosis { get; set; }

        [MaxLength(2000)]
        public string? WorkPerformed { get; set; }

        public OrderStatus Status { get; set; } = OrderStatus.Received;

        // Closing
        public DateTime? DeliveryDate { get; set; }

        public DateTime? CancellationDate { get; set; }

        [MaxLength(500)]
        public string? CancellationReason { get; set; }

        public ICollection<FollowUp> FollowUps { get; set; } = new List<FollowUp>();
    }
}
